import React, { useContext } from 'react';
import { FormattedMessage, useIntl } from 'react-intl';

import Breakpoints from '@dynatrace/strato-design-tokens/breakpoints-js';

import { useBreakpoint } from '../../../core/hooks/useBreakpoint.js';
import { _useId } from '../../../core/hooks/useId.js';
import { Label } from '../../../forms/forms-core/components/label/Label.js';
import { SelectV2 } from '../../../forms/selectv2/Select.js';
import { Flex } from '../../../layouts-core/flex/Flex.js';
import { Text } from '../../../typography/Text.js';
import { TablePaginationContext } from '../../contexts/TablePaginationContext.js';
import { dataTableMessages } from '../messages.js';

type PageIndexSelectProps = {
  onChange: (value: number | null) => void;
};

export function PageIndexSelect(props: PageIndexSelectProps) {
  const { pageCount, pageIndex } = useContext(TablePaginationContext);
  const { onChange } = props;

  const id = _useId();
  const intl = useIntl();
  const mobileScreen = useBreakpoint(
    `(max-width: ${Breakpoints.Max.Mobile}px)`,
  );

  // An array of zero-based index integers corresponding to available pages in the table
  const pageCountArray = Array.from({ length: pageCount }, (_, i) => i);

  return (
    <Flex flexWrap="nowrap" alignItems="center">
      <Label htmlFor={id}>
        <Text textStyle="base" as="p">
          <FormattedMessage
            description="Label for page selection dropdown."
            defaultMessage="Page"
            id="LCNiBr0aBntMq391"
          />
        </Text>
      </Label>
      <SelectV2
        id={id}
        value={pageIndex}
        onChange={onChange}
        aria-label={intl.formatMessage(dataTableMessages.selectPage)}
      >
        <SelectV2.Content>
          {pageCountArray.length === 0 ? (
            <SelectV2.Option key={'pageIndex-0'} id={0} value={0}>
              {0}
            </SelectV2.Option>
          ) : (
            pageCountArray.map((pageIndex) => (
              <SelectV2.Option
                key={`pageIndex-${pageIndex}`}
                id={pageIndex}
                value={pageIndex}
              >
                {pageIndex + 1}
              </SelectV2.Option>
            ))
          )}
        </SelectV2.Content>
      </SelectV2>
      {!mobileScreen && (
        <Label htmlFor={id}>
          <Text as="span" textStyle="base" style={{ whiteSpace: 'nowrap' }}>
            <FormattedMessage
              description="Text displaying the amount of pages."
              defaultMessage="of {totalPages}"
              id="HzhWa5UT4EGJIstf"
              values={{ totalPages: pageCount }}
            />
          </Text>
        </Label>
      )}
    </Flex>
  );
}
